// the caller's own thread; the conflict's update is held to the same owner.
func (q *Queries) UpsertLink(ctx context.Context, arg UpsertLinkParams) (UpsertLinkRow, error) {
	row := q.db.QueryRow(ctx, upsertLink,
		arg.ExpiresAt,
		arg.ShareToken,
		arg.ContentHash,
		arg.SnapshotData,
		arg.MessageIds,
		arg.ThreadID,
		arg.UserID,
	)
	var i UpsertLinkRow
	err := row.Scan(
		&i.ID,
		&i.ShareToken,
		&i.ExpiresAt,
		&i.IsNew,
	)
	return i, err
}
